(let [s @infra.dev.window.lifecycle/service-state w @(:world s) cfg @(:config s)] (prn {:pid (.pid (java.lang.ProcessHandle/current)) :heap-max-bytes (.maxMemory (Runtime/getRuntime)) :world-atom-identity (System/identityHashCode (:world s)) :window (:window s) :render-worker-alive (.isAlive (:thread s)) :sim-worker-alive (.isAlive (:sim-thread s)) :service-error (some-> (:error s) str) :ui-error (some-> (:ui/error-state cfg) str) :world (select-keys w [:tick :genesis/sim-time :arc/current :demo/scenario :demo/fixture?]) :states (frequencies (vals (get-in w [:components domain.ecs.components/matter-state]))) :loaded-default-options (select-keys @#'domain.genesis.bootstrap/default-world-options [:seed :gas-count :nebula-mass :nebula-radius :spin :turb :metallicity]) :config (select-keys cfg [:width :height :mode :ui/cursor-free? :volumetric?]) :camera (select-keys @(:camera s) [:target :position :distance])}))
